"""Figures and tables of the paper from results/ (Section 7.5; convention: every figure is generated by a script from results/).

Figure style: scripts/figures/ieee_style.py (IEEE column widths, Times, Okabe-Ito colours, a marker and line style per system,
no title inside the figure; the content is described in the caption). Every quantity has a 95 % CI.
Output: <out>/fig*.pdf (vector, fonts embedded) and .png (600 dpi); <out>/tables.md.
Regenerate every figure: scripts/figures/make_all_figures.(sh|cmd).
"""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

import numpy as np

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "scripts" / "figures"))
from ieee_style import (COL, GRID, HATCH, INK, INK2, LS, MRK, ONE_COL, SURF, TWO_COL, panel, plt,  # noqa: E402,F401
                        save, style)

WARD = ("W-img", "W-A0", "W-pay", "W-comb")
SYSORDER = ("PQ-PKS", "REF-U", "BL5", "BL5-L")


def fig2_prop1(out, n=2000, seed=5):
    """Prop. 2: (a) number of preimages of the Compress_10 cells; (b) LLR distribution, raw ML-KEM-768 ciphertexts against uniform strings."""
    sys.path.insert(0, str(ROOT / "src"))
    from collections import Counter
    from pqpks.analysis import dpub
    from pqpks.crypto import fips203, hpke
    cnt = Counter(fips203.compress(np.arange(3329), 10).tolist())
    pre = np.array([cnt[j] for j in range(1024)])
    kem = hpke.MlKem768()
    _, pk = kem.generate()
    raw = np.array([dpub.mlkem_raw_llr(hpke.setup_base_s(kem, pk, b"fig2")[0]) for _ in range(n)])
    rng = np.random.default_rng(seed)
    uni = np.array([dpub.mlkem_raw_llr(rng.integers(0, 256, 1088, dtype=np.uint8).tobytes()) for _ in range(n)])
    fig, axes = plt.subplots(1, 2, figsize=(TWO_COL, 2.15), gridspec_kw={"width_ratios": [0.75, 1.6], "wspace": 0.28})
    ax = axes[0]
    style(ax)
    vals, c = np.unique(pre, return_counts=True)
    ax.bar(vals, c, width=0.5, color=COL["PQ-PKS"], edgecolor=INK, lw=0.5)
    for v, k in zip(vals, c):
        ax.text(v, k + 12, f"{k}", ha="center", va="bottom", fontsize=8)
    ax.set_xticks(vals)
    ax.set_xlim(2.4, 4.6)
    ax.set_ylim(0, 880)
    ax.set_xlabel(r"preimages per cell of $\mathrm{Compress}_{10}$")
    ax.set_ylabel("number of cells (of 1024)")
    panel(ax, "(a)")
    ax = axes[1]
    style(ax)
    bins = np.linspace(min(raw.min(), uni.min()), max(raw.max(), uni.max()), 46)
    ax.hist(uni, bins=bins, histtype="stepfilled", color=COL["REF-U"], alpha=0.25, lw=0)
    ax.hist(uni, bins=bins, histtype="step", color=COL["REF-U"], lw=0.9, ls="--")
    ax.hist(raw, bins=bins, histtype="stepfilled", color=COL["PQ-PKS"], alpha=0.25, lw=0, hatch="////")
    ax.hist(raw, bins=bins, histtype="step", color=COL["PQ-PKS"], lw=0.9)
    ax.axvline(0, color=INK, lw=0.7, ls=":")
    ymax = ax.get_ylim()[1]
    ax.set_ylim(0, ymax * 1.32)
    ax.text(bins[0] + 0.3, ymax * 1.27, "uniform strings", ha="left", va="top", fontsize=8)
    ax.text(bins[-1] - 0.3, ymax * 1.27, "raw ML-KEM-768 ciphertexts", ha="right", va="top", fontsize=8)
    ax.set_xlabel(r"LLR statistic $\Lambda$ over the 768 coefficients of $\mathbf{u}$")
    ax.set_ylabel("count")
    panel(ax, "(b)")
    save(fig, out, "fig2_prop1_llr")
    return 0.5 * (np.mean(raw > 0) + np.mean(uni <= 0))


def fig5_e1(S, out, screen):
    pv = np.load(screen / "e1_pos_pvals_k1536_b4096.npy")
    fig, axes = plt.subplots(1, 2, figsize=(TWO_COL, 2.25), gridspec_kw={"width_ratios": [1.55, 1], "wspace": 0.3})
    ax = axes[0]
    style(ax)
    m = pv.size
    ax.scatter(np.arange(m), -np.log10(np.maximum(pv, 1e-300)), s=0.6, color=INK, lw=0, rasterized=True)
    thr = -np.log10(0.05 / m)
    ax.axhline(thr, color=COL["REF-U"], lw=0.9, ls="--")
    ax.text(m * 0.985, thr - 0.12, "Bonferroni/Holm, 5%", ha="right", va="top", fontsize=7.5)
    ax.set_xlim(0, m)
    ax.set_ylim(0, thr + 0.6)
    ax.set_xlabel("bit position of the public syndrome ($B=4096$)")
    ax.set_ylabel(r"$-\log_{10} p$ (binomial test)")
    panel(ax, "(a)")
    ax = axes[1]
    style(ax)
    e1 = S["E1"]
    bs = [256, 512, 1024, 2048, 4096, 8192]
    xs = np.arange(len(bs))
    ax.axhspan(-0.02, 0.02, color=GRID, lw=0, zorder=0)
    ax.axhline(0, color=INK, lw=0.5)
    for k, (lab, key, off, name) in enumerate((("LLR, fixed threshold", "llr_fixed", -0.13, "PQ-PKS"),
                                               ("learned (logistic)", "learned", 0.13, "REF-U"))):
        vals, lo, hi = [], [], []
        for b in bs:
            r = e1.get(f"e1_k1536_b{b}")
            if r is None:
                vals.append(np.nan); lo.append(np.nan); hi.append(np.nan); continue
            if key == "llr_fixed":
                v, (a, c) = r["llr_fixed_diff"], r["llr_fixed_ci95"]
            else:
                v, (a, c, _) = r["learned_adv"], r["learned_ci95"]
            vals.append(v); lo.append(v - a); hi.append(c - v)
        ax.errorbar(xs + off, vals, yerr=[lo, hi], fmt=MRK[name], ms=3.6, lw=0.9, capsize=2,
                    color=COL[name], mfc=COL[name] if k == 0 else SURF, label=lab)
    ax.set_xticks(xs, [str(b) for b in bs])
    ax.set_xlabel("bucket $B$")
    ax.set_ylabel("advantage against uniform")
    ax.legend(loc="upper left", handlelength=1.2)
    ax.set_ylim(-0.075, 0.12)
    panel(ax, "(b)")
    save(fig, out, "fig5_e1_syndrome")


def fig6_dpub(S, out):
    fig, ax = plt.subplots(figsize=(ONE_COL, 2.3))
    style(ax)
    for name in ("BL5", "BL5-L", "PQ-PKS", "REF-U"):
        r = S["E2E3"].get(f"0.4/{name}")
        if r is None:
            continue
        Ms = sorted(int(m) for m in r["dpub_acc"] if m.isdigit())
        ys = [r["dpub_acc"][str(m)] for m in Ms]
        ax.plot(Ms, ys, marker=MRK[name], ls=LS[name], color=COL[name], mfc=SURF if name in ("REF-U", "BL5-L") else COL[name],
                label=name)
        c1 = r["dpub_acc"].get("1_ci95")
        if c1:
            ax.errorbar([1], [ys[0]], yerr=[[ys[0] - c1[0]], [c1[1] - ys[0]]], color=COL[name], capsize=2, lw=0.8)
    cM = {1: 0.899, 2: 0.980}
    ax.scatter(list(cM), list(cM.values()), marker="_", s=90, color=INK, lw=1.0, zorder=5, label=r"lower bound $c_M$")
    ax.set_xscale("log", base=2)
    ax.set_xticks([1, 2, 4, 8], ["1", "2", "4", "8"])
    ax.minorticks_off()
    ax.set_xlim(0.85, 9.5)
    ax.set_xlabel("independent sessions pooled, $M$")
    ax.set_ylabel(r"accuracy of $D_{\mathrm{pub}}$")
    ax.set_ylim(0.45, 1.03)
    ax.legend(loc="center right", fontsize=7)
    save(fig, out, "fig6_dpub_vs_M")


def _tpr_panel(ax, S, a, legend):
    names = [n for n in SYSORDER if f"{a}/{n}" in S["E2E3"]]
    w = 0.8 / len(names)
    for k, n in enumerate(names):
        r = S["E2E3"][f"{a}/{n}"]
        ys = [r[wd]["TPR@5"] for wd in WARD]
        lo = [r[wd]["TPR@5"] - r[wd]["TPR@5_ci95"][0] for wd in WARD]
        hi = [r[wd]["TPR@5_ci95"][1] - r[wd]["TPR@5"] for wd in WARD]
        x = np.arange(len(WARD)) + (k - (len(names) - 1) / 2) * w
        ax.bar(x, ys, w * 0.9, color=COL[n], hatch=HATCH[n], edgecolor=INK, lw=0.4, label=n)
        ax.errorbar(x, ys, yerr=[lo, hi], fmt="none", ecolor=INK, lw=0.6, capsize=1.2)
    ax.axhline(0.05, color=INK, lw=0.7, ls="--")
    ax.set_xticks(np.arange(len(WARD)), WARD)
    ax.set_ylim(0, 1.05)
    ax.tick_params(axis="x", which="both", top=False)
    if legend:
        ax.legend(loc="upper left", ncol=2, fontsize=7, handlelength=1.6)


def fig7_tpr(S, out):
    fig, axes = plt.subplots(1, 2, figsize=(TWO_COL, 2.25), sharey=True, gridspec_kw={"wspace": 0.08})
    for k, (ax, a) in enumerate(zip(axes, ("0.4", "0.2"))):
        style(ax)
        _tpr_panel(ax, S, a, legend=(k == 0))
        panel(ax, "(a)" if k == 0 else "(b)")
    axes[0].set_ylabel("TPR at 5% FPR")
    save(fig, out, "fig7_tpr_wardens")


def fig8_pe(S, out):
    fig, axes = plt.subplots(1, 2, figsize=(TWO_COL, 2.35), gridspec_kw={"width_ratios": [1.15, 1], "wspace": 0.45})
    ax = axes[0]
    style(ax)
    for n in ("BL5", "BL5-L", "PQ-PKS", "REF-U"):
        al = [a for a in ("0.1", "0.2", "0.4") if f"{a}/{n}" in S["E2E3"]]
        ys = [S["E2E3"][f"{a}/{n}"]["W-img"]["P_E"] for a in al]
        lo = [S["E2E3"][f"{a}/{n}"]["W-img"]["P_E_ci95"][0] for a in al]
        hi = [S["E2E3"][f"{a}/{n}"]["W-img"]["P_E_ci95"][1] for a in al]
        xs = [float(a) for a in al]
        ax.plot(xs, ys, marker=MRK[n], ls=LS[n], color=COL[n], mfc=SURF if n in ("REF-U", "BL5-L") else COL[n], label=n)
        if n in ("PQ-PKS", "REF-U"):
            ax.fill_between(xs, lo, hi, color=COL[n], alpha=0.12, lw=0)
    ax.axhline(0.45, color=INK, lw=0.7, ls="--")
    ast = S.get("alpha_star", {}).get("alpha_star_i")
    if ast:
        ax.axvline(ast, color=INK, lw=0.7, ls=":")
        ax.text(ast + 0.005, 0.505, r"$\alpha^\ast$", fontsize=8.5, ha="left", va="center")
    ax.set_xlabel(r"embedding rate $\alpha$ (bpp)")
    ax.set_ylabel(r"$P_E$ of W-img")
    ax.set_ylim(0.3, 0.52)
    ax.legend(loc="lower left", fontsize=7)
    panel(ax, "(a)")
    ax = axes[1]
    style(ax)
    rows = []
    for a in ("0.1", "0.2", "0.4"):
        for wd in ("W-img", "W-A0", "W-comb"):
            t = S["TOST"].get(f"{a}/PQ-PKS-vs-REF-U/{wd}")
            if t:
                rows.append((rf"$\alpha$ = {a}, {wd}", t))
    ax.axvspan(-0.02, 0.02, color=GRID, lw=0, zorder=0)
    ax.axvline(0, color=INK, lw=0.5)
    vstyle = {"equivalent": ("o", INK, INK), "inconclusive": ("o", INK, SURF), "different": ("x", COL["REF-U"], COL["REF-U"])}
    for k, (lab, t) in enumerate(rows):
        y = len(rows) - 1 - k
        mk, c, fc = vstyle[t["verdict"]]
        ax.plot(t["ci90"], [y, y], color=c, lw=1.0)
        ax.plot([t["diff"]], [y], marker=mk, ms=3.8, color=c, mfc=fc, ls="none")
    ax.set_yticks(range(len(rows)), [r[0] for r in rows][::-1], fontsize=7.5)
    ax.set_xlim(-0.025, 0.025)
    ax.set_xticks([-0.02, -0.01, 0, 0.01, 0.02])
    ax.tick_params(axis="y", which="both", right=False)
    ax.set_xlabel(r"$P_E$(PQ-PKS) $-$ $P_E$(REF-U), 90% CI")
    panel(ax, "(b)")
    save(fig, out, "fig8_pe_alpha_tost")


def fig9_bits(E5, out, S=None):
    """(a) useful bits per image by N at alpha* for the earlier ladder (D0) and the merged ladder (D5); (b) N*_sigma by alpha for D0, D5, D6
    (e5_ladder.json)."""
    L = json.loads((ROOT / "results" / "e5_budget" / "e5_ladder.json").read_text())
    fig, axes = plt.subplots(1, 2, figsize=(TWO_COL, 2.35), gridspec_kw={"wspace": 0.32})
    ax = axes[0]
    style(ax)
    D = L["designs"]
    Ns = [1, 2, 4, 8, 16, 32]
    series = [("D0", "per_image_at_alpha_star_ML-DSA-65", "ML-DSA-65, single ladder", COL["REF-U"], "s", "--", SURF),
              ("D5", "per_image_at_alpha_star_ML-DSA-65", "ML-DSA-65, merged ladder", COL["REF-U"], "s", "-", COL["REF-U"]),
              ("D0", "per_image_at_alpha_star_unsigned_session", "unsigned, single ladder", COL["PQ-PKS"], "o", "--", SURF),
              ("D5", "per_image_at_alpha_star_unsigned_session", "unsigned, merged ladder", COL["PQ-PKS"], "o", "-", COL["PQ-PKS"])]
    for d, key, lab, c, mk, ls, fc in series:
        cur = D[d][key]
        xs = [n for n in Ns if cur.get(str(n)) is not None]
        ax.plot(xs, [cur[str(n)] / 1024 for n in xs], marker=mk, ls=ls, color=c, mfc=fc, label=lab)
    single = D["D5"]["single_unsigned_at_alpha_star_B"] / 1024
    ax.axhline(single, color=INK, lw=0.7, ls=":")
    ax.text(1.05, single + 0.06, "single image", fontsize=7.5, ha="left", va="bottom")
    ax.set_xscale("log", base=2)
    ax.set_xticks(Ns, [str(n) for n in Ns])
    ax.minorticks_off()
    ax.set_xlabel("session length $N$")
    ax.set_ylabel("useful message per image (KiB)")
    ax.legend(loc="lower right", fontsize=6.8)
    panel(ax, "(a)")
    ax = axes[1]
    style(ax)
    if S is not None and S["alpha_star"].get("ci95"):
        lo, hi = S["alpha_star"]["ci95"]
        ax.axvspan(lo, hi, color=GRID, lw=0, zorder=0)
    for d, lab, c, mk, fc in (("D0", r"single ladder, $\sigma$ in image 1", COL["REF-U"], "s", SURF),
                              ("D5", r"merged ladder, $\sigma$ in image 1", COL["PQ-PKS"], "o", COL["PQ-PKS"]),
                              ("D6", r"merged ladder, $\sigma$ in image 2", COL["BL5"], "^", SURF)):
        g = D[d]["sig"]["ML-DSA-65"]["N_star_grid"]
        xs = sorted(float(a) for a in g if g[a] is not None)
        ax.plot(xs, [g[str(a) if str(a) in g else f"{a}"] for a in xs], ls="none", marker=mk, ms=3.2, color=c, mfc=fc, label=lab)
        ax.axvline(D[d]["sig"]["ML-DSA-65"]["alpha_min"], color=c, lw=0.7, ls=":")
    ax.set_yscale("log", base=2)
    ax.set_ylim(1.5, 2 ** 10)
    ax.set_xlim(0.09, 0.31)
    ax.set_xlabel(r"embedding rate $\alpha$ (bpp)")
    ax.set_ylabel(r"break-even length $N^\ast_\sigma$")
    ax.legend(loc="center right", fontsize=6.8)
    panel(ax, "(b)")
    save(fig, out, "fig9_bits_vs_N")


def fig10_budget(E5, out, name="fig10_bit_budget"):
    rows = E5["budget_A8"]
    fig, ax = plt.subplots(figsize=(ONE_COL, 2.55))
    style(ax)
    labels = [f"{r['msg']} B, {r['sig'].replace('none', 'no sig.')}" for r in rows]
    parts = [(r"$\hat c$ (Kemeleon)", [1536] * len(rows), COL["PQ-PKS"], ""),
             ("signature", [3309 if r["sig"] == "ML-DSA-65" else (2420 if r["sig"] == "ML-DSA-44" else 0) for r in rows],
              COL["REF-U"], "////"),
             ("header + tag", [14 + 16] * len(rows), INK2, ""),
             ("padding", [r["pad"] for r in rows], SURF, "...."),
             ("message", [r["msg"] for r in rows], COL["BL5"], "xxxx")]
    left = np.zeros(len(rows))
    for lab, v, c, h in parts:
        ax.barh(range(len(rows)), v, left=left, height=0.62, color=c, hatch=h, edgecolor=INK, lw=0.4, label=lab)
        left += np.array(v)
    ax.set_yticks(range(len(rows)), labels, fontsize=7.5)
    ax.tick_params(axis="y", which="both", right=False, left=False)
    ax.set_xlabel("bytes in the first image")
    budget = int(E5["alpha_star"] * 512 * 512 / 8)
    ax.axvline(budget, color=INK, lw=0.8, ls="--")
    ax.set_ylim(len(rows) - 0.5, -1.1)
    ax.text(budget + 80, -0.78, rf"$\alpha^\ast n/8={budget}$ B", fontsize=7.5, ha="left", va="center")
    ax.legend(loc="upper center", bbox_to_anchor=(0.42, -0.22), ncol=3, fontsize=7, handlelength=1.5, columnspacing=1.0)
    save(fig, out, name)


def tables(S, E4, E5, E6, out):
    L = []
    L.append("| α | System | n | W-img $P_E$ | W-A0 $P_E$ | W-pay $P_E$ | W-comb $P_E$ | W-img TPR@5% | W-pay TPR@5% | ΔTPR (W-pay − W-img) [95 % CI] | $D_{pub}$ acc. M=1 / 2 / 4 |")
    L.append("|---|---|---|---|---|---|---|---|---|---|---|")
    for key, r in S["E2E3"].items():
        a, n = key.split("/")
        d = r["dTPR_pay_minus_img"]
        da = r["dpub_acc"]
        L.append(f"| {a} | {n} | {r['n']} | " + " | ".join(
            f"{r[w]['P_E']:.3f} [{r[w]['P_E_ci95'][0]:.3f}, {r[w]['P_E_ci95'][1]:.3f}]" for w in WARD)
            + f" | {r['W-img']['TPR@5']:.3f} | {r['W-pay']['TPR@5']:.3f} | {d['dTPR']:+.3f} [{d['ci95'][0]:+.3f}, {d['ci95'][1]:+.3f}] | "
            + " / ".join(f"{da.get(str(m), float('nan')):.3f}" for m in (1, 2, 4)) + " |")
    (out / "table_e2e3.md").write_text("\n".join(L) + "\n")
    T = ["| α | Comparison | Warden | Δ$P_E$ | 90 % CI | Verdict (δ = 0.02) |", "|---|---|---|---|---|---|"]
    for k, t in S["TOST"].items():
        a, comp, w = k.split("/")
        T.append(f"| {a} | {comp} | {w} | {t['diff']:+.4f} | [{t['ci90'][0]:+.4f}, {t['ci90'][1]:+.4f}] | {t['verdict']} |")
    (out / "table_tost.md").write_text("\n".join(T) + "\n")
    E = ["| Variant | Bucket | n | LLR diff [95 % CI] | upper |·| | learned adv. [95 % CI] | Holm rejections | pooled byte χ² p |", "|---|---|---|---|---|---|---|---|"]
    for k, r in S["E1"].items():
        _, kb, b = k.split("_")
        E.append(f"| {kb[1:]} B | {b[1:]} | {r['n']} | {r['llr_fixed_diff']:+.4f} [{r['llr_fixed_ci95'][0]:+.4f}, {r['llr_fixed_ci95'][1]:+.4f}] | "
                 f"{r['llr_fixed_upper95_abs']:.4f} | {r['learned_adv']:+.4f} [{r['learned_ci95'][0]:+.4f}, {r['learned_ci95'][1]:+.4f}] | "
                 f"{r['pos_rejections_holm']} | {r['byte_chi2_p_pooled']:.3f} |")
    (out / "table_e1.md").write_text("\n".join(E) + "\n")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default=str(ROOT / "results" / "figures"))
    ap.add_argument("--screen", default=str(ROOT / "results" / "archive" / "pre-confirm" / "screen_v1"))
    ap.add_argument("--e5", default=str(ROOT / "results" / "e5_budget"))
    args = ap.parse_args()
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    screen = Path(args.screen)
    S = json.loads((screen / "summary.json").read_text())
    E5 = json.loads((Path(args.e5) / "e5_summary.json").read_text())
    E4p = ROOT / "results" / "archive" / "pre-confirm" / "e4_functional" / "e4_summary.json"
    E6p = ROOT / "results" / "archive" / "pre-confirm" / "e6_perf" / "e6_summary.json"
    E4 = json.loads(E4p.read_text()) if E4p.exists() else None
    E6 = json.loads(E6p.read_text()) if E6p.exists() else None
    fig2_prop1(out)
    fig5_e1(S, out, screen)
    fig6_dpub(S, out)
    fig7_tpr(S, out)
    fig8_pe(S, out)
    fig9_bits(E5, out, S)
    fig10_budget(E5, out)
    tables(S, E4, E5, E6, out)
    print("figures in", out)


if __name__ == "__main__":
    main()
